def ring_solver(inp, wall, bg):
 H=len(inp);W=len(inp[0]);seen=set();o=[row[:] for row in inp];comps=[]
 for r in range(H):
  for c in range(W):
   if inp[r][c]==wall or (r,c) in seen:continue
   seen.add((r,c));q=deque([(r,c)]);co=[]
   while q:
    p=q.popleft();co.append(p)
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     z=(p[0]+dr,p[1]+dc)
     if 0<=z[0]<H and 0<=z[1]<W and inp[z[0]][z[1]]!=wall and z not in seen:
      seen.add(z);q.append(z)
   S=set(co);d={};q=deque()
   for p in co:
    r,c=p
    if any((r+dr,c+dc) not in S for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):d[p]=0;q.append(p)
   while q:
    p=q.popleft()
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     z=(p[0]+dr,p[1]+dc)
     if z in S and z not in d:d[z]=d[p]+1;q.append(z)
   seeds={d[p]:inp[p[0]][p[1]] for p in co if inp[p[0]][p[1]] not in (bg,wall)}
   if seeds:
    seq=[seeds[k] for k in sorted(seeds)]
    for p in co:o[p[0]][p[1]]=seq[d[p]%len(seq)]
   comps.append((co,d,seeds))
 return o,comps
