      if (r,colidx) in blocked or (preserve_wall and orig[r][colidx]==3): continue
      grid[r][colidx]=base
  for off,color in enumerate(rings,1):
    top,bot,left,right=r0+off,r1-off,c0+off,c1-off
    for r in range(top,bot+1):
